define([],function(){return{init:function(rootSelector){const root=rootSelector?document.querySelector(rootSelector):document;if(!root)return;const tabs=root.querySelectorAll(".lce-tab"),panels=root.querySelectorAll(".lce-tabpanel");tabs.forEach(tab=>{tab.addEventListener("click",()=>{const id=tab.getAttribute("data-tab");tabs.forEach(t=>t.classList.remove("is-active")),tab.classList.add("is-active"),panels.forEach(p=>{p.classList.toggle("is-active",p.getAttribute("data-panel")===id)})})});const sections=root.querySelectorAll(".lce-section-head");sections.forEach(head=>{head.addEventListener("click",()=>{const section=head.closest(".border")||head.parentElement,items=section.querySelector(".lce-items"),icon=head.querySelector("i.fa-chevron-down, i.fa-chevron-up");items.classList.toggle("is-open"),icon&&(icon.classList.toggle("fa-chevron-down",!items.classList.contains("is-open")),icon.classList.toggle("fa-chevron-up",items.classList.contains("is-open")))})});const expandBtn=root.querySelector("#expand-all");expandBtn&&expandBtn.addEventListener("click",()=>{root.querySelectorAll(".lce-items").forEach(el=>el.classList.add("is-open")),root.querySelectorAll(".lce-section-head i.fa-chevron-down, .lce-section-head i.fa-chevron-up").forEach(icon=>{icon.classList.remove("fa-chevron-down"),icon.classList.add("fa-chevron-up")})});const collapseBtn=root.querySelector("#collapse-all");collapseBtn&&collapseBtn.addEventListener("click",()=>{root.querySelectorAll(".lce-items").forEach(el=>el.classList.remove("is-open")),root.querySelectorAll(".lce-section-head i.fa-chevron-down, .lce-section-head i.fa-chevron-up").forEach(icon=>{icon.classList.add("fa-chevron-down"),icon.classList.remove("fa-chevron-up")})}),root.querySelectorAll(".lce-items").forEach(el=>el.classList.add("is-open")),root.querySelectorAll(".lce-section-head i.fa-chevron-down, .lce-section-head i.fa-chevron-up").forEach(icon=>{icon.classList.remove("fa-chevron-down"),icon.classList.add("fa-chevron-up")})}}});
